using AutoMapper;
using ProductManagement.Features.Product;
using ProductManagement.Features.Product.DTOs;

namespace ProductManagement.Common.Mapping.Resolvers;

// Deprecated: AvailabilityStatusResolver moved into AdvanceProductMappingProfile as a private static function.
// File retained for history; safe to delete if desired.
public class AvailabilityStatusResolver : IValueResolver<Product, ProductProfileDTO, string>
{
    public string Resolve(Product source, ProductProfileDTO destination, string destMember, ResolutionContext context)
    {
        return source.IsAvaliable ? "Available" : "Unavailable";
    }
}

using AutoMapper;
using ProductManagement.Features.Product;
using ProductManagement.Features.Product.DTOs;
using System.Linq;

namespace ProductManagement.Common.Mapping.Resolvers;

// Deprecated: BrandInitialsResolver moved into AdvanceProductMappingProfile as a private static function.
// File retained for history; safe to delete if desired.
public class BrandInitialsResolver : IValueResolver<Product, ProductProfileDTO, string>
{
    public string Resolve(Product source, ProductProfileDTO destination, string destMember, ResolutionContext context)
    {
        var brand = !string.IsNullOrWhiteSpace(source.Description) ? source.Description : source.Name;
        var parts = brand.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length == 0) return string.Empty;
        var initials = string.Concat(parts.Select(p => p[0])).ToUpperInvariant();
        return initials;
    }
}

