using AutoMapper;
using ProductManagement.Features.Product;
using ProductManagement.Features.Product.DTOs;
using System.Globalization;

namespace ProductManagement.Common.Mapping.Resolvers;

// Deprecated: PriceFormatterResolver moved into AdvanceProductMappingProfile as a private static function.
// File retained for history; safe to delete if you prefer.
public class PriceFormatterResolver : IValueResolver<Product, ProductProfileDTO, string>
{
    public string Resolve(Product source, ProductProfileDTO destination, string destMember, ResolutionContext context)
    {
        return source.Price.ToString("C", CultureInfo.CurrentCulture);
    }
}

using AutoMapper;
using ProductManagement.Features.Product;
using ProductManagement.Features.Product.DTOs;

namespace ProductManagement.Common.Mapping.Resolvers;

// Deprecated: ProductAgeResolver moved into AdvanceProductMappingProfile as a private static function.
// File retained for history; safe to delete if desired.
public class ProductAgeResolver : IValueResolver<Product, ProductProfileDTO, string>
{
    public string Resolve(Product source, ProductProfileDTO destination, string destMember, ResolutionContext context)
    {
        var days = (DateTime.UtcNow - source.ReleaseDate).Days;
        return days switch
        {
            < 0 => "Not released",
            0 => "New",
            1 => "1 day",
            _ => $"{days} days"
        };
    }
}

namespace ProductManagement.Features.Product;

public class ProductProfileDTO
{
    Guid Id { get; init; }
    string Name { get; init; }
    string Brand { get; init; }
    string SKU { get; init; }
    decimal Price { get; init; }
    string FormattedPrice { get; init; }
    DateTime ReleaseDate { get; init; }
    DateTime CreatedAt { get; init; }
    string? ImageUrl { get; init; }

    bool IsAvailable { get; init; }
    int StockQuantity { get; init; }
    string ProductAge { get; init; }
    string BrandInitials { get; init; }
    string AvailabilityStatus { get; init; }
}

namespace ProductManagement.Features.Product.DTOs;

public class ProductProfileDTO
{
    public Guid Id { get; init; }
    public string Name { get; init; } = string.Empty;
    public string Brand { get; init; } = string.Empty;
    public string SKU { get; init; } = string.Empty;
    public decimal Price { get; init; }
    public string FormattedPrice { get; init; } = string.Empty;
    public DateTime ReleaseDate { get; init; }
    public DateTime CreatedAt { get; init; }
    public string? ImageUrl { get; init; }

    public bool IsAvailable { get; init; }
    public int StockQuantity { get; init; }
    public string ProductAge { get; init; } = string.Empty;
    public string BrandInitials { get; init; } = string.Empty;
    public string AvailabilityStatus { get; init; } = string.Empty;
    public string Category { get; init; } = string.Empty;
}

